from collections import Counter
def f(inp, ring=True):
    g=[r[:] for r in inp]; H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    hlines=set(i for i in range(H) if len(set(g[i]))==1 and g[i][0]!=bg)
    vlines=set(j for j in range(W) if len({g[i][j] for i in range(H)})==1 and g[0][j]!=bg)
    lc=g[hlines.pop()][0] if hlines else g[0][vlines.pop()]
    marks=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg and i not in hlines and j not in vlines]
    res=[r[:] for r in g]
    for (mi,mj) in marks:
        mkcol=g[mi][mj]
        horiz = bool(hlines)
        # rays perpendicular to lines axis
        for sgn in (1,-1):
            idx=mi if horiz else mj; step=sgn
            k=idx+step
            while 0<=k < H if horiz else True and k<W if not horiz else True:
                pass
        # simpler: ray cells get marker color until a line is crossed
        def cast(r,c,dir_):
            for _ in range(max(H,W)):
                r+=dir_[0]; c+=dir_[1]
                if not(0<=r<H and 0<=c<W): return None
                if (horiz and r in hlines) or (not horiz and c in vlines): break
                res[r][c]=mkcol
        dirs=[]
        if horiz:
            dirs=[(1,0),(-1,0)]
        else:
            dirs=[(0,1),(0,-1)]
        for dr,dc in dirs: cast(mi,mj,(dr,dc))
        # ring around first crossing on each of 4 directions
        crossings=[]
        for dr,dc in dirs:
            r,c=mi,mj
            while True:
                r+=dr; c+=dc
                if not(0<=r<H and 0<=c<W): break
                if (horiz and r in hlines) or (not horiz and c in vlines):
                    crossings.append((r,c,dr,dc)); break
        for cr,cc,_,_ in crossings:
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    nr,nc=cr+di,cc+dj
                    if not(0<=nr<H and 0<=nc<W): continue
                    res[nr][nc]= mkcol if (di==0 and dj==0) else lc
    return res

